from fastapi import FastAPI
from pydantic import BaseModel, Field, EmailStr

class UsuarioRegistro(BaseModel):
    username: str = Field(min_length=3, max_length=20)
    edad: int = Field(ge=18, le=120, description="Mayor de edad")
    activo: bool = True

app = FastAPI()

@app.post("/usuarios", status_code=201)
def crear_usuario(payload: UsuarioRegistro):
    # payload es una instancia validada de UsuarioRegistro
    return {"mensaje": f"Usuario {payload.username} creado", "edad": payload.edad}
